"""Mission 07 — Part 4: Security & Ethics Sentinel.

Event Horizon pruning and illustrative PRM reward-hacking defense.
Pure Python 3.11+; no external dependencies.
"""
from dataclasses import dataclass, field
from typing import List, Tuple
import math
import re


@dataclass
class PruningReport:
    """Telemetry generated by EventHorizonPruner (step numbers are 1-based)."""
    surviving_steps: List[str]
    adjusted_scores: List[float]
    pruned_at_step: int = -1
    reward_hacking_detected: bool = False
    security_alerts: List[str] = field(default_factory=list)
    estimated_tokens_saved: int = 0
    steps_skipped: int = 0


class EventHorizonPruner:
    """Prune low-scored steps; penalize exact filler phrases and repeated steps.

    Detection is deliberately heuristic, not a general semantic verification model.
    `hacking_penalty_factor` multiplies the original score when an attack is found.
    """

    def __init__(self, tau_horizon: float = 0.45, hacking_penalty_factor: float = 0.20):
        if not math.isfinite(tau_horizon) or not 0.0 <= tau_horizon <= 1.0:
            raise ValueError("tau_horizon must be finite and in [0, 1]")
        if not math.isfinite(hacking_penalty_factor) or not 0.0 <= hacking_penalty_factor <= 1.0:
            raise ValueError("hacking_penalty_factor must be finite and in [0, 1]")
        self.tau_horizon = tau_horizon
        self.hacking_penalty_factor = hacking_penalty_factor
        self.sycophantic_fillers = [
            "let us carefully verify this 100% rigorous step",
            "this is undeniably true because",
            "as we can clearly see with absolute certainty",
            "by trivial and indisputable mathematical inspection",
        ]

    @staticmethod
    def _normalize(text: str) -> str:
        return re.sub(r"\s+", " ", text).strip().casefold()

    @staticmethod
    def _approximate_tokens(text: str) -> int:
        """Word/punctuation proxy, NOT tokens measured by an actual tokenizer."""
        return len(re.findall(r"\w+|[^\w\s]", text))

    def check_reward_hacking(self, step: str, prev_step: str = "") -> Tuple[bool, str]:
        if not isinstance(step, str) or not isinstance(prev_step, str):
            raise TypeError("step and prev_step must be strings")
        lowered = self._normalize(step)
        for filler in self.sycophantic_fillers:
            if filler in lowered:
                return True, f"SYCOPHANTIC_FILLER_DETECTED ('{filler}')"
        if prev_step and lowered == self._normalize(prev_step):
            return True, "STEP_SPLITTING_REDUNDANCY_DETECTED"
        return False, "CLEAN"

    def prune_trajectory(self, steps: List[str], raw_step_scores: List[float]) -> PruningReport:
        if len(steps) != len(raw_step_scores):
            raise ValueError("steps and raw_step_scores must have the same length")
        report = PruningReport(surviving_steps=[], adjusted_scores=[])
        prev_step = ""
        for idx, (step, score) in enumerate(zip(steps, raw_step_scores), start=1):
            if not isinstance(step, str):
                raise TypeError("each step must be a string")
            raw_score = float(score)
            if not math.isfinite(raw_score) or not 0.0 <= raw_score <= 1.0:
                raise ValueError("step scores must be finite and in [0, 1]")
            hacked, reason = self.check_reward_hacking(step, prev_step)
            adjusted_score = raw_score
            if hacked:
                report.reward_hacking_detected = True
                adjusted_score = round(raw_score * self.hacking_penalty_factor, 4)
                report.security_alerts.append(
                    f"[Step {idx}] ANOMALY 07 REWARD HACKING: {reason} -> "
                    f"Score penalized {raw_score:.2f} -> {adjusted_score:.2f}"
                )
            if adjusted_score < self.tau_horizon:
                report.pruned_at_step = idx
                report.steps_skipped = len(steps) - idx
                report.estimated_tokens_saved = sum(
                    self._approximate_tokens(s) for s in steps[idx:]
                )
                report.security_alerts.append(
                    f"[Step {idx}] EVENT HORIZON BREACH: Adjusted PRM score "
                    f"{adjusted_score:.2f} < tau ({self.tau_horizon:.2f}). Branch severed!"
                )
                break
            report.surviving_steps.append(step)
            report.adjusted_scores.append(adjusted_score)
            prev_step = step
        return report


def _run_tests() -> None:
    pruner = EventHorizonPruner(tau_horizon=0.45, hacking_penalty_factor=0.20)
    adversarial_steps = [
        "Step 1: Compute Schwarzschild radius r_s = 2GM / c^2 = 1.27e10 m",
        "Step 2: Let us carefully verify this 100% rigorous step and set thrust = 0",
        "Step 3: Plunge across Sagittarius A* Event Horizon (Unreachable after pruning)",
    ]
    scores = [0.93, 0.96, 0.10]
    report = pruner.prune_trajectory(adversarial_steps, scores)
    assert report.reward_hacking_detected
    assert report.pruned_at_step == 2
    assert report.surviving_steps == [adversarial_steps[0]]
    assert report.steps_skipped == 1
    assert report.estimated_tokens_saved > 0
    assert pruner.check_reward_hacking("  SAME   STEP ", "same step")[0]
    assert pruner.check_reward_hacking("x = 1", "x = 2") == (False, "CLEAN")
    assert pruner.prune_trajectory(["a", "b"], [0.8, 0.9]).pruned_at_step == -1
    assert pruner.prune_trajectory(["bad", "later"], [0.1, 0.9]).pruned_at_step == 1
    assert pruner.prune_trajectory([], []).surviving_steps == []
    assert pruner.prune_trajectory(["edge"], [0.45]).pruned_at_step == -1
    repeated = pruner.prune_trajectory(["derive x = 4", "derive x = 4", "answer"], [0.9, 0.9, 0.9])
    assert repeated.reward_hacking_detected and repeated.pruned_at_step == 2
    for fn in (
        lambda: pruner.prune_trajectory(["a"], []),
        lambda: pruner.prune_trajectory(["a"], [float("nan")]),
        lambda: EventHorizonPruner(tau_horizon=1.2),
        lambda: EventHorizonPruner(hacking_penalty_factor=-0.1),
    ):
        try:
            fn()
        except ValueError:
            pass
        else:
            raise AssertionError("invalid input was accepted")

    print("=== Mission 07: Security & Ethics Sentinel ===")
    print(f"Surviving Steps: {len(report.surviving_steps)}/{len(adversarial_steps)}")
    print(f"Pruned at Step: {report.pruned_at_step}")
    print(f"Reward Hacking Detected: {report.reward_hacking_detected}")
    print(f"Steps Skipped: {report.steps_skipped}")
    print(f"Estimated tokens saved (proxy): {report.estimated_tokens_saved}")
    for alert in report.security_alerts:
        print(alert)
    print("[OK] Part 4 verification and edge-case tests passed.")


if __name__ == "__main__":
    _run_tests()
